// Affinda parse successful — extract skills and experience
const affindaData = $input.item.json;
const data = affindaData.data ?? affindaData;

// Extract skills from Affinda response
let parsedSkills = [];
if (data.skills && Array.isArray(data.skills)) {
  parsedSkills = data.skills.map(s => s.name ?? s.skill ?? s).filter(Boolean);
} else if (data.data?.skills) {
  parsedSkills = data.data.skills.map(s => s.name ?? s.skill ?? s).filter(Boolean);
}

// Extract work experience
let workExperience = [];
const workHist = data.workExperience ?? data.data?.workExperience ?? [];
workExperience = workHist.map(w => ({
  company: w.organization?.name ?? w.company ?? '',
  role: w.jobTitle?.name ?? w.role ?? '',
  duration: w.dates?.monthsInPosition ?? 0
}));

// Extract total experience years
const totalExp = data.totalYearsExperience ?? data.data?.totalYearsExperience ?? 0;

// Pass through candidate info + parsed data
return [{
  json: {
    candidate_id: $('Set Candidate Variables').item.json.candidate_id,
    full_name: $('Set Candidate Variables').item.json.full_name,
    email: $('Set Candidate Variables').item.json.email,
    job_id: $('Set Candidate Variables').item.json.job_id,
    job_title: $('Set Candidate Variables').item.json.job_title,
    raw_skills: $('Set Candidate Variables').item.json.raw_skills ?? [],
    parsed_skills: parsedSkills,
    work_experience: workExperience,
    total_experience_years: totalExp,
    resume_parsed: true
  }
}];

// No resume URL — use raw_skills as fallback
const candidateVars = $('Set Candidate Variables').item.json;

console.log('No resume URL for candidate:', candidateVars.candidate_id, '— using raw skills as fallback');

return [{
  json: {
    candidate_id: candidateVars.candidate_id,
    full_name: candidateVars.full_name,
    email: candidateVars.email,
    job_id: candidateVars.job_id,
    job_title: candidateVars.job_title,
    raw_skills: candidateVars.raw_skills ?? [],
    parsed_skills: [],
    work_experience: [],
    total_experience_years: 0,
    resume_parsed: false
  }
}];

// Merge raw_skills + parsed_skills and deduplicate
const d = $input.item.json;

const raw = Array.isArray(d.raw_skills) ? d.raw_skills : [];
const parsed = Array.isArray(d.parsed_skills) ? d.parsed_skills : [];

// Combine and deduplicate (case insensitive)
const combined = [...raw, ...parsed];
const seen = new Set();
const merged = combined.filter(skill => {
  if (!skill) return false;
  const key = String(skill).toLowerCase().trim();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

console.log(`Candidate ${d.candidate_id} — merged skills: ${merged.length} (raw: ${raw.length}, parsed: ${parsed.length})`);

return [{
  json: {
    ...d,
    merged_skills: merged
  }
}];

// Pass through candidate data with normalized skills from Next.js response
const normalizeResponse = $input.item.json;
const prevData = $('Merge Raw + Parsed Skills').item.json;

return [{
  json: {
    candidate_id: prevData.candidate_id,
    full_name: prevData.full_name,
    email: prevData.email,
    job_id: prevData.job_id,
    job_title: prevData.job_title,
    merged_skills: prevData.merged_skills,
    normalized_skills: normalizeResponse.normalized ?? prevData.merged_skills,
    total_experience_years: prevData.total_experience_years ?? 0
  }
}];

// Handle resume scoring result — continue even if scoring failed
const scoreResult = $input.item.json;
const prevData = $('Prepare for Scoring').item.json;

const resumeScore = scoreResult.resumeScore ?? null;

if (resumeScore !== null) {
  console.log(`✅ Resume score for ${prevData.candidate_id}: ${resumeScore}/10`);
} else {
  console.warn(`⚠️ Resume scoring failed for ${prevData.candidate_id} — continuing anyway`);
}

return [{
  json: {
    candidate_id: prevData.candidate_id,
    full_name: prevData.full_name,
    email: prevData.email,
    job_id: prevData.job_id,
    job_title: prevData.job_title,
    normalized_skills: prevData.normalized_skills,
    resume_score: resumeScore,
    scoring_success: resumeScore !== null
  }
}];

// Prepare email data combining score result + token
const tokenData = $input.item.json;
const scoreData = $('Handle Score Result').item.json;
const candObj = tokenData.candidate ?? tokenData;

const assessmentToken = candObj.assessmentToken ?? null;
const candidateName = candObj.fullName ?? scoreData.full_name ?? 'Candidate';
const firstName = candidateName.split(' ')[0];
let email = candObj.email || scoreData.email || 'ahmadraza792003@gmail.com';

// Resend test domain (onboarding@resend.dev) restricts sending to @example.com / @placeholder.com
if (!email || email.includes('@example.com') || email.includes('@placeholder.com')) {
  email = 'ahmadraza792003@gmail.com';
}

const jobTitle = scoreData.job_title || 'Software Developer';
const assessmentLink = candObj.assessmentUrl ?? `http://localhost:3000/assessment/${assessmentToken}`;

if (!assessmentToken) {
  console.error('❌ No assessment token found for candidate:', scoreData.candidate_id);
}

return [{
  json: {
    candidate_id: scoreData.candidate_id,
    full_name: candidateName,
    first_name: firstName,
    email: email,
    job_id: scoreData.job_id,
    job_title: jobTitle,
    assessment_token: assessmentToken,
    assessment_link: assessmentLink,
    resume_score: scoreData.resume_score,
    ready_to_email: assessmentToken !== null && email !== null
  }
}];

