// Log email sent successfully
const emailResult = $input.item.json;
const emailData = $('Prepare Email Data').item.json;

console.log(`✅ Assessment email sent to: ${emailData.email}`);
console.log(`   Candidate: ${emailData.full_name}`);
console.log(`   Job: ${emailData.job_title}`);
console.log(`   Email ID: ${emailResult.id ?? 'unknown'}`);

return [{
  json: {
    status: 'email_sent',
    candidate_id: emailData.candidate_id,
    email: emailData.email,
    email_id: emailResult.id ?? null
  }
}];

// Token not found — log error and skip email
const emailData = $('Prepare Email Data').item.json;

console.error(`❌ Cannot send email — no assessment token for candidate: ${emailData.candidate_id}`);
console.error(`   Name: ${emailData.full_name}, Email: ${emailData.email}`);

return [{
  json: {
    status: 'email_skipped',
    candidate_id: emailData.candidate_id,
    reason: 'no_assessment_token'
  }
}];

// Final log for this candidate
const result = $input.item.json;

console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
console.log('✅ W2 — Candidate Processing Complete');
console.log('Candidate ID:', result.candidate_id ?? 'unknown');
console.log('Status:', result.status ?? 'unknown');
console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

return [{ json: result }];
